import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Gallery = () => {
  const [images, setImages] = useState([]);
  const [image, setImage] = useState(null);

  useEffect(() => {
    fetchImages();
  }, []);

  const fetchImages = async () => {
    const { data } = await axios.get('/api/gallery');
    setImages(data);
  };

  const uploadImage = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('image', image);

    try {
      const config = {
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
      };

      await axios.post('/api/gallery', formData, config);
      alert('Image uploaded successfully');
      fetchImages(); // Refresh after upload
    } catch (error) {
      alert('Failed to upload image');
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="mb-4">Event Gallery</h2>

      {/* Image Upload Form (Visible only for Admin) */}
      {localStorage.getItem('isAdmin') === 'true' && (
        <form onSubmit={uploadImage} className="mb-4">
          <div className="mb-3">
            <input
              type="file"
              className="form-control"
              onChange={(e) => setImage(e.target.files[0])}
              required
            />
          </div>
          <button type="submit" className="btn btn-primary">
            Upload Image
          </button>
        </form>
      )}

      {/* Display Images */}
      <div className="row">
        {images.map((img) => (
          <div key={img._id} className="col-md-3 mb-3">
            <img
              src={img.imageUrl}
              alt="Event"
              className="img-fluid rounded"
              style={{ height: '200px', objectFit: 'cover' }}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

export default Gallery;
